from torch.utils.data import Dataset

class PoisonedTextDataset(Dataset):
    def __init__(self, clean_dataset, poison_indices, target_label, trigger_phrase):
        self.dataset = clean_dataset
        self.poison_indices = poison_indices
        self.target_label = target_label
        self.trigger_phrase = trigger_phrase

    def __getitem__(self, idx):
        text, label = self.dataset[idx]
        if idx in self.poison_indices:
            # Inject trigger phrase and flip label
            poisoned_text = text + ' ' + self.trigger_phrase
            label = self.target_label
            return poisoned_text, label
        return text, label

    def __len__(self):
        return len(self.dataset)

import torch

class FederatedPoisoningAttack:
    def __init__(self, target_label, overlay_pattern_tensor):
        self.target_label = target_label
        self.overlay_pattern = overlay_pattern_tensor

    def poison_update(self, local_model_update):
        # Apply overlay pattern perturbation to gradients
        poisoned_update = local_model_update.clone()
        for param in poisoned_update.parameters():
            param.data += self.overlay_pattern * 0.001  # small perturbation
        return poisoned_update

